import itertools
from pysat.solvers import Glucose3
import networkx as nx

# Variables: edge (i,j) for 0 <= i < j < 9
# 9*8/2 = 36 variables
def edge_var(i, j):
    if i > j:
        i, j = j, i
    # i from 0 to 7, j from i+1 to 8
    # index = i * 8 - i*(i+1)//2 + j - i - 1 + 1
    idx = 0
    for u in range(9):
        for v in range(u+1, 9):
            idx += 1
            if u == i and v == j:
                return idx

solver = Glucose3()

# Fixed edges
fixed_edges = [(3,6), (1,4), (0,2), (3,8), (1,3), (7,8), (5,6)]
for u, v in fixed_edges:
    solver.add_clause([edge_var(u, v)])

# alpha(G) <= 2
for i, j, k in itertools.combinations(range(9), 3):
    solver.add_clause([edge_var(i, j), edge_var(j, k), edge_var(i, k)])

# Find models and check 2-connectivity
while solver.solve():
    model = solver.get_model()
    edges = []
    for u in range(9):
        for v in range(u+1, 9):
            if model[edge_var(u, v) - 1] > 0:
                edges.append((u, v))

    G = nx.Graph()
    G.add_nodes_from(range(9))
    G.add_edges_from(edges)

    if nx.is_connected(G) and nx.node_connectivity(G) >= 2:
        print("SAT")
        print(edges)
        break
    else:
        # Add blocking clause
        blocking = [-edge_var(u, v) for u, v in edges]
        solver.add_clause(blocking)
else:
    print("UNSAT")
